package com.amit.jobagent.matching;import com.amit.jobagent.audit.*;import com.amit.jobagent.common.error.*;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import jakarta.validation.Valid;import java.util.UUID;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/job-evaluations/{evaluationId}/feedback")@SecurityRequirement(name="basicAuth")public class EvaluationFeedbackController{private final EvaluationFeedbackRepository repo;private final JobEvaluationRepository evaluations;private final AuditService audit;public EvaluationFeedbackController(EvaluationFeedbackRepository r,JobEvaluationRepository e,AuditService a){repo=r;evaluations=e;audit=a;}@PostMapping@Transactional public FeedbackResponse put(@PathVariable UUID evaluationId,@Valid@RequestBody FeedbackRequest r){if(!evaluations.existsById(evaluationId))throw new ResourceNotFoundException("Evaluation was not found");var current=repo.findByEvaluationId(evaluationId);var f=current.orElseGet(()->new EvaluationFeedback(evaluationId,r));if(current.isPresent()){if(r.recordVersion()!=null&&f.getRecordVersion()!=r.recordVersion())throw new ConflictException("Feedback was changed by another request");f.apply(r);}var saved=repo.saveAndFlush(f);audit.record(current.isPresent()?AuditEventType.EVALUATION_FEEDBACK_UPDATED:AuditEventType.EVALUATION_FEEDBACK_CREATED,"EvaluationFeedback",saved.getId(),"{}");return map(saved);}@GetMapping@Transactional(readOnly=true)public FeedbackResponse get(@PathVariable UUID evaluationId){return map(repo.findByEvaluationId(evaluationId).orElseThrow(()->new ResourceNotFoundException("Feedback was not found")));}private static FeedbackResponse map(EvaluationFeedback f){return new FeedbackResponse(f.getId(),f.evaluationId,f.label,f.correct,f.notes,f.getRecordVersion(),f.getCreatedAt(),f.getUpdatedAt());}}
